INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2634919, 364980, 10080, '<td valign="top">Powerful! 10</td>', 'Powerful! 10', '2006-07-19 01:17:40.000000', NULL, 1),
(2634942, 365785, 4210, '<td valign="top">I must admit, this photo came up as the first thumbnail for me, and my absolute FIRST thought was "oh I''m screwed" (re: my own challenge entry). Great lighting, colour, DOF control.</td>', 'I must admit, this photo came up as the first thumbnail for me, and my absolute FIRST thought was "oh I''m screwed" (re: my own challenge entry). Great lighting, colour, DOF control.', '2006-07-19 01:19:53.000000', NULL, 1),
(2634994, 365680, 21714, '<td valign="top">Stunning!</td>', 'Stunning!', '2006-07-19 01:25:10.000000', NULL, 1),
(2634998, 363212, 24073, '<td valign="top">I am so distraut that you didn''t walk up 10yds and shoot this.  I know it had to of been done on purpose, but the lines in the sky, and the lines of the road would of been enough to meet the challenge.</td>', 'I am so distraut that you didn''t walk up 10yds and shoot this.  I know it had to of been done on purpose, but the lines in the sky, and the lines of the road would of been enough to meet the challenge.', '2006-07-19 01:26:30.000000', NULL, 1),
(2635007, 366082, 15711, '<td valign="top">Clever! Love the green of the inch worm. This is really fun. Nice sense of movement and I love the DOF 8</td>', 'Clever! Love the green of the inch worm. This is really fun. Nice sense of movement and I love the DOF 8', '2006-07-19 01:27:41.000000', NULL, 1),
(2635035, 366176, 15711, '<td valign="top">perfect!!! The lighting, the clarity. Great portrait. 10 BRAVO</td>', 'perfect!!! The lighting, the clarity. Great portrait. 10 BRAVO', '2006-07-19 01:31:24.000000', NULL, 1),
(2635051, 363903, 36470, '<td valign="top">Excellent portrait!  The only thing I could nit pick about is I think it MIGHT have been better with their feet in the frame.</td>', 'Excellent portrait!  The only thing I could nit pick about is I think it MIGHT have been better with their feet in the frame.', '2006-07-19 01:32:23.000000', NULL, 1),
(2635063, 365471, 25787, '<td valign="top">Great idea, good looking model.  Lighting is way to harsh; a flash I guess.  Try at least bouncing the flash off of the ceiling to soften it.</td>', 'Great idea, good looking model.  Lighting is way to harsh; a flash I guess.  Try at least bouncing the flash off of the ceiling to soften it.', '2006-07-19 01:33:34.000000', NULL, 1),
(2635091, 363886, 24073, '<td valign="top">You know the cool thing about going outside the box like this, is that it grinds at your mind, and will not let you forget about it.  Alot of images here, even the really good ones are forgettable, but this one is not.  IMHO, I think you have done a wonderful job, and tackled a sort of supremacy (&lt;---if thats the right word) in stand out photography.  GL.</td>', 'You know the cool thing about going outside the box like this, is that it grinds at your mind, and will not let you forget about it.  Alot of images here, even the really good ones are forgettable, but this one is not.  IMHO, I think you have done a wonderful job, and tackled a sort of supremacy (<---if thats the right word) in stand out photography.  GL.', '2006-07-19 01:36:03.000000', NULL, 1),
(2635092, 365954, 21714, '<td valign="top">Beautifully photographed. Very nice work.</td>', 'Beautifully photographed. Very nice work.', '2006-07-19 01:36:04.000000', NULL, 1),
(2635094, 365340, 36470, '<td valign="top">Incredible image.  Best of luck to you! 10</td>', 'Incredible image.  Best of luck to you! 10', '2006-07-19 01:36:07.000000', NULL, 1),
(2635100, 364759, 36470, '<td valign="top">I think this is an excellent image.  However, I question if it really meets the challenge.</td>', 'I think this is an excellent image.  However, I question if it really meets the challenge.', '2006-07-19 01:37:09.000000', NULL, 1),
(2635107, 365313, 24073, '<td valign="top">Not a huge fan of the infared, but I am also not biased, I will vote according to the merit, and in that case, very nice indeed.</td>', 'Not a huge fan of the infared, but I am also not biased, I will vote according to the merit, and in that case, very nice indeed.', '2006-07-19 01:37:45.000000', NULL, 1),
(2635128, 363430, 42957, '<td valign="top">I''d like to see this in BW instead of sepia.  Very different from the other entries.  I like how you continued the swirly lines on the fan.  The button stud is a little distracting, but the question mark in the star is cute.</td>', 'I''d like to see this in BW instead of sepia.  Very different from the other entries.  I like how you continued the swirly lines on the fan.  The button stud is a little distracting, but the question mark in the star is cute.', '2006-07-19 01:40:27.000000', NULL, 1),
(2635129, 364987, 24073, '<td valign="top">wonderful portraiture, but I think this is going to have problems with the DNMC club.  I like it.  GL.</td>', 'wonderful portraiture, but I think this is going to have problems with the DNMC club.  I like it.  GL.', '2006-07-19 01:40:29.000000', NULL, 1),
