(2635480, 366032, 59754, '<td valign="top">I like simple and I like minimalist, but this is a little too simple (and small).  Perhaps more saturation to bring out the sunset would have helped.</td>', 'I like simple and I like minimalist, but this is a little too simple (and small).  Perhaps more saturation to bring out the sunset would have helped.', '2006-07-19 02:31:19.000000', NULL, 1),
(2635486, 365471, 59754, '<td valign="top">The lighting here is a bit way too sharp.  Nice model and cool concept though, good luck.</td>', 'The lighting here is a bit way too sharp.  Nice model and cool concept though, good luck.', '2006-07-19 02:31:55.000000', NULL, 1),
(2635492, 363286, 59754, '<td valign="top">A bit too sharp, and the ugly color noise comes through as a result (even in monochrome).</td>', 'A bit too sharp, and the ugly color noise comes through as a result (even in monochrome).', '2006-07-19 02:33:06.000000', NULL, 1),
