(2639992, 364556, 58452, '<td valign="top">Simply love the colors superimposed on the white.</td>', 'Simply love the colors superimposed on the white.', '2006-07-19 21:45:31.000000', NULL, 1),
(2639995, 365321, 58452, '<td valign="top">Lovely shafts of light.</td>', 'Lovely shafts of light.', '2006-07-19 21:46:21.000000', NULL, 1),
(2640003, 365345, 42957, '<td valign="top">Those are wonderful drawings.</td>', 'Those are wonderful drawings.', '2006-07-19 21:47:56.000000', NULL, 1),
