(2640246, 366176, 61505, '<td valign="top">Fantastic image. Sharp, contrasty and an interesting take on the lines theme. I like it. Just maybe a little bit too much empty space on the left.</td>', 'Fantastic image. Sharp, contrasty and an interesting take on the lines theme. I like it. Just maybe a little bit too much empty space on the left.', '2006-07-19 22:45:21.000000', NULL, 1),
(2640249, 365937, 41008, '<td valign="top">Beautiful, though a tad over-sharpened, this is my favorite so far.</td>', 'Beautiful, though a tad over-sharpened, this is my favorite so far.', '2006-07-19 22:45:50.000000', NULL, 1),
(2640256, 363430, 61505, '<td valign="top">Sensuous and makes me want to go to a cafe... I dunno I''m weird. Nice shot.</td>', 'Sensuous and makes me want to go to a cafe... I dunno I''m weird. Nice shot.', '2006-07-19 22:46:34.000000', NULL, 1),
