INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2640598, 363530, 61138, '<td valign="top">Energy! This image is really alive. The angles, DOF, colours, refractions...very bold and interesting.<br/> <br/>My one small note is that it feels heavy on the right.</td>', 'Energy! This image is really alive. The angles, DOF, colours, refractions...very bold and interesting. My one small note is that it feels heavy on the right.', '2006-07-20 00:05:02.000000', NULL, 1),
(2640601, 365002, 22975, '<td valign="top">gorgeous.  congrats on a great photo!!</td>', 'gorgeous.  congrats on a great photo!!', '2006-07-20 00:07:58.000000', NULL, 1),
(2640602, 364177, 61138, '<td valign="top">Lovely. The image is crisp. The colours vibrant.</td>', 'Lovely. The image is crisp. The colours vibrant.', '2006-07-20 00:07:59.000000', NULL, 1),
(2640616, 364711, 61138, '<td valign="top">Nice choice of subject and light source. The visual weight of the foreground column stabilizes the image. Without it, the angle would seem a little askew. Nice work. An 8.</td>', 'Nice choice of subject and light source. The visual weight of the foreground column stabilizes the image. Without it, the angle would seem a little askew. Nice work. An 8.', '2006-07-20 00:13:43.000000', NULL, 1),
(2640630, 363430, 22975, '<td valign="top">ingenious.  i love this!</td>', 'ingenious.  i love this!', '2006-07-20 00:17:59.000000', NULL, 1),
(2640635, 365260, 22975, '<td valign="top">very cool angle.  love this.</td>', 'very cool angle.  love this.', '2006-07-20 00:19:29.000000', NULL, 1),
(2640678, 366169, 62249, '<td valign="top">Scene needs better lighting.</td>', 'Scene needs better lighting.', '2006-07-20 00:32:05.000000', NULL, 1),
(2640683, 365575, 62249, '<td valign="top">NIce.</td>', 'NIce.', '2006-07-20 00:33:03.000000', NULL, 1),
