(2643605, 364504, 60223, '<td valign="top">Great picture, colors, angle.</td>', 'Great picture, colors, angle.', '2006-07-20 19:51:18.000000', NULL, 1),
(2643624, 366178, 60223, '<td valign="top">Picture appears to be crooked.  Picture is nice but doesn''t have much flavor to it for me.  Did you try any pictures near ground level?</td>', 'Picture appears to be crooked.  Picture is nice but doesn''t have much flavor to it for me.  Did you try any pictures near ground level?', '2006-07-20 19:53:37.000000', NULL, 1),
(2643660, 363903, 60223, '<td valign="top">Good picture but I fail to see how the two little girls have much to do with this challenge yet be so prominently displayed in this photo.  They look adorable, just out of place for this challenge.  And it''s not nice to amputate peoples feet :)</td>', 'Good picture but I fail to see how the two little girls have much to do with this challenge yet be so prominently displayed in this photo.  They look adorable, just out of place for this challenge.  And it''s not nice to amputate peoples feet :)', '2006-07-20 19:56:30.000000', NULL, 1),
(2643679, 364034, 60223, '<td valign="top">Funny.  Btw, might want to clean the dust from your camera, many spots to be seen.</td>', 'Funny.  Btw, might want to clean the dust from your camera, many spots to be seen.', '2006-07-20 19:58:02.000000', NULL, 1),
(2643703, 364905, 60223, '<td valign="top">Really like this photo and the lines shown here, works well for this challenge and for a photo on it''s own.  Nitpick would be to crop (or clone before printing) out the plant sticking into the picture on the bottom left.  Good work.</td>', 'Really like this photo and the lines shown here, works well for this challenge and for a photo on it''s own.  Nitpick would be to crop (or clone before printing) out the plant sticking into the picture on the bottom left.  Good work.', '2006-07-20 20:00:08.000000', NULL, 1),
(2643723, 364698, 51802, '<td valign="top">Well done!  I like how you angled this shot, it thows you off balance.</td>', 'Well done!  I like how you angled this shot, it thows you off balance.', '2006-07-20 20:02:32.000000', NULL, 1),
(2643736, 365844, 51802, '<td valign="top">Great shot, it looks like gates at a coliseum.</td>', 'Great shot, it looks like gates at a coliseum.', '2006-07-20 20:03:22.000000', NULL, 1),
(2643744, 365264, 51802, '<td valign="top">Great shot for this challenge!</td>', 'Great shot for this challenge!', '2006-07-20 20:03:46.000000', NULL, 1),
(2643749, 365343, 51802, '<td valign="top">I find this shot interesting.  However, the angles don''t work for me.  It would have given it more pop if the drawn lines were fanned out more, and the each pencil were lined up with it''s own color.  Kinda like as if the line were projecting out from the tip.</td>', 'I find this shot interesting.  However, the angles don''t work for me.  It would have given it more pop if the drawn lines were fanned out more, and the each pencil were lined up with it''s own color.  Kinda like as if the line were projecting out from the tip.', '2006-07-20 20:04:06.000000', NULL, 1),
(2643791, 365192, 51802, '<td valign="top">Seems over processed.  The saturation is so high that artifacts are now showing.</td>', 'Seems over processed.  The saturation is so high that artifacts are now showing.', '2006-07-20 20:11:41.000000', NULL, 1),
(2643803, 365961, 51802, '<td valign="top">Haveing the closest edge of the leaf so out of focus really hurts the overall image.</td>', 'Haveing the closest edge of the leaf so out of focus really hurts the overall image.', '2006-07-20 20:12:44.000000', NULL, 1),
