(2660431, 365525, 30959, '<td valign="top">What a stunning shot this is, congratulations on a well deserved blue.</td>', 'What a stunning shot this is, congratulations on a well deserved blue.', '2006-07-26 01:32:23.000000', NULL, 0),
(2660448, 364108, 30959, '<td valign="top">A rare happenstance. Nicely captured and congratulations on having the eye and skills to know where to go and how to get it.. and the ribbon.</td>', 'A rare happenstance. Nicely captured and congratulations on having the eye and skills to know where to go and how to get it.. and the ribbon.', '2006-07-26 01:34:22.000000', NULL, 0),
