(2662458, 364108, 50695, '<td valign="top">Congratulations, I''m thrilled to see such an idiosyncratic, living picture win a ribbon.</td>', 'Congratulations, I''m thrilled to see such an idiosyncratic, living picture win a ribbon.', '2006-07-26 09:21:13.000000', NULL, 0),
