(2662494, 363790, 50695, '<td valign="top">I gave you a 7 just for the "fascinatin'' rhythm"</td>', 'I gave you a 7 just for the "fascinatin'' rhythm"', '2006-07-26 09:29:58.000000', NULL, 0),
